using System;
using System.IO;
using System.Linq;
using System.Text;
using NUnit.Framework;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using XRScan.Avatar;

namespace XRScan.Tests.EditMode
{
    /// <summary>
    /// Contract between the avatar models in <c>Assets/XRScan/Avatar/Models</c> (the CI Companion is
    /// generated by <c>tools/avatar/build_ci_companion.py</c>) and the avatar pipeline: the face mesh
    /// lip-sync binds to, the visemes it drives, the head bone gaze uses, and model provenance.
    /// </summary>
    public class AvatarModelTests
    {
        private const string ModelsDir = "Assets/XRScan/Avatar/Models";
        private const string CompanionModel = ModelsDir + "/CI_Companion.glb";

        [Serializable] private class GltfRoot { public GltfAsset asset; }
        [Serializable] private class GltfAsset { public string generator; public string copyright; }

        private static GameObject LoadCompanion()
        {
            var model = AssetDatabase.LoadAssetAtPath<GameObject>(CompanionModel);
            Assert.IsNotNull(model, $"{CompanionModel} is missing or failed to import");
            return model;
        }

        private static SkinnedMeshRenderer CompanionFace()
        {
            var face = AvatarLoadController.FindFaceRenderer(LoadCompanion().transform);
            Assert.IsNotNull(face, "no skinned mesh with blend shapes on the companion avatar");
            return face;
        }

        [Test]
        public void CompanionAvatar_FaceMeshCarriesEveryLipSyncViseme()
        {
            var mesh = CompanionFace().sharedMesh;
            var missing = AvatarLipSync.VisemeBlendShapes.Where(v => mesh.GetBlendShapeIndex(v) < 0).ToArray();
            CollectionAssert.IsEmpty(missing, "visemes AvatarLipSync maps but the face mesh lacks");
            // VisemeController's amplitude fallback.
            Assert.GreaterOrEqual(mesh.GetBlendShapeIndex("mouthOpen"), 0);
        }

        [Test]
        public void CompanionAvatar_FaceRestsWithEveryBlendShapeAtZero()
        {
            var face = CompanionFace();
            for (int i = 0; i < face.sharedMesh.blendShapeCount; i++)
                Assert.AreEqual(0f, face.GetBlendShapeWeight(i), 1e-4f, face.sharedMesh.GetBlendShapeName(i));
        }

        [Test]
        public void CompanionAvatar_HasHeadBone()
        {
            var bones = LoadCompanion().GetComponentsInChildren<Transform>(true);
            Assert.IsTrue(bones.Any(t => t.name == "Head"), "no 'Head' transform for AvatarLoadController.Head");
        }

        /// <summary>
        /// Both scenes with an avatar (the app scene and the in-Editor development scene with the mock
        /// wiring) instance the companion model, and lip-sync drives its "Face" mesh.
        /// </summary>
        [TestCase("Assets/XRScan/App/Scenes/XRScan_Main.unity")]
        [TestCase("Assets/XRScan/App/Scenes/XRScan_Dev.unity")]
        public void Scene_AvatarIsTheCompanionWithLipSyncOnItsFace(string scenePath)
        {
            var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Additive);
            try
            {
                var loader = scene.GetRootGameObjects()
                    .SelectMany(root => root.GetComponentsInChildren<AvatarLoadController>(true))
                    .FirstOrDefault();
                Assert.IsNotNull(loader, $"{scenePath}: no AvatarLoadController");

                var source = PrefabUtility.GetCorrespondingObjectFromSource(loader.gameObject);
                Assert.AreEqual(CompanionModel, source != null ? AssetDatabase.GetAssetPath(source) : "<not a model instance>",
                    $"{scenePath}: the avatar does not instance the companion model");

                var lipSync = loader.GetComponent<AvatarLipSync>();
                Assert.IsNotNull(lipSync, $"{scenePath}: no AvatarLipSync on the avatar");
                using (var serialized = new SerializedObject(lipSync))
                {
                    var face = serialized.FindProperty("faceRenderer").objectReferenceValue as SkinnedMeshRenderer;
                    Assert.IsNotNull(face, $"{scenePath}: AvatarLipSync has no face renderer");
                    Assert.AreEqual("Face", face.name, $"{scenePath}: lip-sync is bound to the wrong mesh");
                }
            }
            finally
            {
                EditorSceneManager.CloseScene(scene, true);
            }
        }

        [Test]
        public void AvatarModels_CarryACopyrightThatIsNotReadyPlayerMe()
        {
            var models = Directory.GetFiles(ModelsDir, "*.glb");
            CollectionAssert.IsNotEmpty(models);
            foreach (var path in models)
            {
                var asset = JsonUtility.FromJson<GltfRoot>(ReadGlbJson(path)).asset;
                Assert.IsNotNull(asset, path);
                Assert.IsFalse(string.IsNullOrWhiteSpace(asset.copyright), $"{path}: glTF asset block has no copyright");
                StringAssert.DoesNotContain("Ready Player Me", asset.copyright ?? "", path);
                StringAssert.DoesNotContain("Ready Player Me", asset.generator ?? "", path);
            }
        }

        /// <summary>The JSON chunk of a binary glTF (header: magic, version, length; then chunk length + type).</summary>
        private static string ReadGlbJson(string path)
        {
            var bytes = File.ReadAllBytes(path);
            Assert.AreEqual(0x46546C67u, BitConverter.ToUInt32(bytes, 0), $"{path} is not a GLB");
            int length = (int)BitConverter.ToUInt32(bytes, 12);
            Assert.AreEqual(0x4E4F534Au, BitConverter.ToUInt32(bytes, 16), $"{path}: first chunk is not JSON");
            return Encoding.UTF8.GetString(bytes, 20, length);
        }
    }
}
